// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        // Wide admissible domain: any strictly positive deposit amount.
        amount = bound(amount, 1, type(uint256).max / 2);

        // Fund the test contract (the owner of c, since it deployed it) and
        // push `amount` ETH into c via its payable fallback.
        vm.deal(address(this), amount);
        (bool depOk, ) = address(c).call{value: amount}("");
        require(depOk, "deposit failed");

        // The owner (this test contract) has no receive/fallback that accepts
        // Ether, so the reference C's withdrawAll -> withdraw ->
        // payable(msg.sender).transfer(amount) REVERTS. The mutant's emptied
        // withdrawAll performs no transfer and therefore SUCCEEDS.
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // General rule: for every admissible deposit, withdrawAll by the owner
        // must actually execute the payout path (here it must revert, since the
        // owner cannot accept ETH). The bug breaks this: withdrawAll silently
        // succeeds without ever transferring.
        assertTrue(!ok);
    }
}
